import { useNavigate } from "react-router";
import { Badge } from "@/presentation/components/ui/badge";
import { Button } from "@/presentation/components/ui/button";
import { Card } from "@/presentation/components/ui/card";
import { SectionHeader } from "../components/atoms/SectionHeader";
import { ForecastCell } from "../components/molecules/ForecastCell";
import { LearnableCallout } from "../components/molecules/LearnableCallout";
import { QuickActionCard } from "../components/molecules/QuickActionCard";
import { StagePill } from "../components/molecules/StagePill";
import {
	ACHIEVEMENT_DEFS,
	AchievementBadge,
} from "../components/organisms/AchievementBadge";
import { HeatmapWidget } from "../components/organisms/HeatmapWidget";
import { NotificationBanner } from "../components/organisms/NotificationBanner";
import { useApp } from "../hooks/useApp";

const STAGES = [
	"Apprentice",
	"Guru",
	"Master",
	"Enlightened",
	"Burned",
] as const;

function newCountLabel(count: number, noun: string): string {
	return `${count} new ${noun}${count === 1 ? "" : "s"}`;
}

export function Dashboard() {
	const { state, lesson, review, dashboard, vocab } = useApp();
	const navigate = useNavigate();

	const nextLesson = lesson.getNextScript();
	const nextVocabLesson =
		lesson.getVocabUnlockedCount() > 0 ? vocab.getNextLesson() : null;
	const nextGrammarLesson = lesson.getNextGrammar();
	const nextSentenceLesson = lesson.getNextSentence();
	const scriptDueCount = review.getDueCount("script");
	const vocabDueCount = review.getDueCount("vocab");
	const grammarDueCount = review.getDueCount("grammar");
	const sentenceDueCount = review.getDueCount("sentence");
	const dueCount =
		scriptDueCount + vocabDueCount + grammarDueCount + sentenceDueCount;
	const timeUntilNextReview = review.getTimeUntilNextReview();
	const forecast = review.getForecast();
	const leechCount = dashboard.getLeechCount();
	const stages = dashboard.getStageCounts();
	const achievements = state.achievements ?? [];
	const reviewButtonCount = [
		scriptDueCount,
		vocabDueCount,
		grammarDueCount,
		sentenceDueCount,
	].filter((n) => n > 0).length;
	const reviewGridClass = `grid gap-3 ${reviewButtonCount === 2 ? "grid-cols-2" : "grid-cols-1"}`;

	return (
		<div className="space-y-6 py-4">
			<NotificationBanner />

			{/* 1. Primary Action Card */}
			<div
				className="rounded-2xl p-6"
				style={{
					background:
						dueCount > 0 ? "var(--color-primary)" : "var(--color-surface-2)",
				}}
			>
				{dueCount > 0 ? (
					<>
						<div className="flex items-center gap-3 mb-4">
							<Badge variant="secondary">{dueCount} due</Badge>
							<span
								className="text-sm"
								style={{ color: "rgba(255,255,255,0.7)" }}
							>
								Cards ready for review
							</span>
						</div>
						<div className={reviewGridClass}>
							{scriptDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/review")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Script ({scriptDueCount})
								</Button>
							)}
							{vocabDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/vocabulary")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Vocab ({vocabDueCount})
								</Button>
							)}
							{grammarDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/grammar")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Grammar ({grammarDueCount})
								</Button>
							)}
							{sentenceDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/sentences")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Sentences ({sentenceDueCount})
								</Button>
							)}
						</div>
					</>
				) : (
					<>
						<p
							className="text-sm font-semibold mb-2"
							style={{ color: "var(--color-text-muted)" }}
						>
							All reviews complete
						</p>
						{timeUntilNextReview && (
							<p
								className="text-lg font-semibold"
								style={{ color: "var(--color-text)" }}
							>
								Next review in {timeUntilNextReview}
							</p>
						)}
					</>
				)}
			</div>

			{/* 2. Secondary Actions (2-col) — evergreen entry points, always in the
			    same two slots regardless of what else is unlocked. */}
			<div className="grid grid-cols-2 gap-3">
				{nextLesson ? (
					<QuickActionCard
						label="Next Lesson"
						value={`Lesson ${nextLesson}`}
						onClick={() => navigate(`/lesson/${nextLesson}`)}
					/>
				) : (
					<QuickActionCard label="Script" value="All done ✓" disabled />
				)}
				{/* Mobile-reachable entry point for the practice game — the
				    mobile tab row has no room for it. */}
				<QuickActionCard
					label="Game"
					value="Practice round"
					onClick={() => navigate("/game")}
				/>
			</div>

			{/* Ready to Learn — every pool with new content ready, regardless of
			    whether anything is due for review (due reviews are the primary
			    action card above; this is about content the learner hasn't seen
			    yet). Each entry mirrors StartLessonUseCase's own gating (rank
			    window, prerequisites, apprentice cap), so a callout here always
			    means starting that lesson will actually work. */}
			{(nextVocabLesson || nextGrammarLesson || nextSentenceLesson) && (
				<div className="space-y-3">
					<SectionHeader className="mb-1">Ready to Learn</SectionHeader>
					{nextVocabLesson && (
						<LearnableCallout
							label="Vocabulary"
							detail={newCountLabel(nextVocabLesson.words.length, "word")}
							onClick={() => navigate("/vocabulary")}
							accentColor="var(--color-enlightened)"
						/>
					)}
					{nextGrammarLesson && (
						<LearnableCallout
							label="Grammar"
							detail={newCountLabel(
								nextGrammarLesson.grammarPoints.length,
								"grammar point",
							)}
							onClick={() => navigate("/grammar")}
							accentColor="var(--color-guru)"
						/>
					)}
					{nextSentenceLesson && (
						<LearnableCallout
							label="Sentences"
							detail={newCountLabel(
								nextSentenceLesson.sentences.length,
								"sentence",
							)}
							onClick={() => navigate("/sentences")}
							accentColor="var(--color-master)"
						/>
					)}
				</div>
			)}

			{/* 3. Stage Progress Pills */}
			{Object.values(stages).some((v) => v > 0) && (
				<div>
					<SectionHeader className="mb-3">Progress</SectionHeader>
					<div className="flex gap-2 overflow-x-auto pb-1">
						{STAGES.map((stage) => (
							<StagePill
								key={stage}
								stage={stage}
								count={stages[stage.toLowerCase() as keyof typeof stages]}
								onClick={() => navigate(`/progress/${stage}`)}
							/>
						))}
					</div>
				</div>
			)}

			{/* 6. Upcoming Reviews Forecast */}
			{Object.keys(state.cards).length > 0 && (
				<div>
					<SectionHeader className="mb-3">Upcoming Reviews</SectionHeader>
					<div className="grid grid-cols-5 gap-2 text-center">
						<ForecastCell label="Now" value={forecast.dueNow} />
						<ForecastCell label="1 hr" value={forecast.nextHour} />
						<ForecastCell label="24 hr" value={forecast.next24Hours} />
						<ForecastCell label="3 days" value={forecast.next3Days} />
						<ForecastCell label="7 days" value={forecast.next7Days} />
					</div>
				</div>
			)}

			{/* 7. Leech Warning */}
			{leechCount > 0 && (
				<div
					className="rounded-xl p-4 flex justify-between items-center"
					style={{
						background:
							"color-mix(in srgb, var(--color-danger) 8%, transparent)",
						borderLeft: "3px solid var(--color-danger)",
					}}
				>
					<div>
						<div
							className="text-sm font-semibold"
							style={{ color: "var(--color-danger)" }}
						>
							Leeches Detected
						</div>
						<div
							className="text-xs mt-0.5"
							style={{ color: "var(--color-text-muted)" }}
						>
							Cards that keep failing — consider extra study
						</div>
					</div>
					<div
						className="text-2xl font-bold"
						style={{ color: "var(--color-danger)" }}
					>
						{leechCount}
					</div>
				</div>
			)}
		</div>
	);
}
=== ConversationPracticePage.tsx ===
import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@/presentation/components/ui/button";
import type {
	ConversationJudgeResult,
	ConversationOpeningResult,
	ConversationVerdict,
} from "../../domain/conversation/types";
import { useApp } from "../hooks/useApp";
import { useMicRecorder } from "../hooks/useMicRecorder";

/**
 * How each verdict reads. `"unscored"` is deliberately neither of the other
 * two: it is the backend admitting it could not judge the turn, so showing
 * it as a fail would blame the learner for a system fault, and showing it as
 * a pass would be a lie.
 */
const VERDICT_PRESENTATION: Record<
	ConversationVerdict,
	{ label: string; note: string; color: string }
> = {
	pass: {
		label: "Good answer",
		note: "That works as a reply.",
		color: "var(--color-success, #15803d)",
	},
	fail: {
		label: "Not quite",
		note: "That does not answer the question yet — try again.",
		color: "var(--color-danger, #b91c1c)",
	},
	unscored: {
		label: "Could not be scored",
		note: "Something went wrong on the backend, so this turn was not judged. It does not count against you.",
		color: "var(--color-text-muted, #6b7280)",
	},
};

const BACKEND_UNAVAILABLE_MESSAGE =
	"The conversation backend is not running, so there is nothing to talk to yet. Start it locally and reload this page.";

/**
 * Spoken conversation practice: hear one Thai question, record a reply, see
 * whether the local backend judged it as an acceptable answer.
 *
 * Phase 1 asks exactly one hardcoded question — real, vocabulary-scoped
 * content is phase 2's job. There is deliberately no self-rating, no SRS
 * card and no history entry: a judge verdict is a different kind of signal
 * from a recall rating, and how it should feed the scheduler, if at all, is
 * not this task's call to make.
 */
export function ConversationPracticePage() {
	const { conversationPractice, vocab } = useApp();
	const [opening, setOpening] = useState<ConversationOpeningResult | null>(
		null,
	);
	const [judgement, setJudgement] = useState<ConversationJudgeResult | null>(
		null,
	);
	const [judging, setJudging] = useState(false);
	const { state, audioBlob, start, stop, reset } = useMicRecorder();
	const audioRef = useRef<HTMLAudioElement | null>(null);

	useEffect(() => {
		let cancelled = false;
		// The learner's real known-vocabulary snapshot, sourced from their
		// SRS state — never a placeholder list. A learner with nothing
		// learned yet sends a real empty array, not an omitted field.
		const knownWords = vocab.getLearnedEntries().map((entry) => entry.thai);
		conversationPractice.getOpening(knownWords).then((result) => {
			if (!cancelled) setOpening(result);
		});
		return () => {
			cancelled = true;
		};
	}, [conversationPractice, vocab]);

	const questionText = opening?.status === "ok" ? opening.questionText : null;
	const questionAudioUrl =
		opening?.status === "ok" ? opening.questionAudioUrl : null;

	// One finished take → one judgement. Keyed on the blob's identity, so a
	// re-render never re-submits the same recording.
	useEffect(() => {
		if (state !== "stopped" || !audioBlob || !questionText) return;
		let cancelled = false;
		setJudging(true);
		conversationPractice.judgeReply(questionText, audioBlob).then((result) => {
			if (cancelled) return;
			setJudgement(result);
			setJudging(false);
		});
		return () => {
			cancelled = true;
		};
	}, [state, audioBlob, questionText, conversationPractice]);

	// Same replay convention as SentenceListeningChallenge /
	// SymbolDictationChallenge: a fresh `Audio` per press, the previous one
	// stopped first, rejections swallowed (autoplay policy).
	const playQuestion = useCallback(() => {
		if (!questionAudioUrl) return;
		if (audioRef.current) {
			audioRef.current.pause();
			audioRef.current.currentTime = 0;
		}
		const audio = new Audio(questionAudioUrl);
		audioRef.current = audio;
		audio.play().catch(() => {});
	}, [questionAudioUrl]);

	useEffect(
		() => () => {
			audioRef.current?.pause();
			audioRef.current = null;
		},
		[],
	);

	function tryAgain() {
		setJudgement(null);
		reset();
	}

	if (opening === null) {
		return <p className="p-4">Connecting to the conversation backend…</p>;
	}

	// No question means nothing to reply to — so no record control at all,
	// rather than one that would silently do nothing.
	if (opening.status === "unavailable") {
		return (
			<div className="space-y-4 p-4">
				<h1 className="text-xl font-semibold">Conversation practice</h1>
				<p role="alert">{BACKEND_UNAVAILABLE_MESSAGE}</p>
			</div>
		);
	}

	return (
		<div className="space-y-6 p-4">
			<h1 className="text-xl font-semibold">Conversation practice</h1>

			<section className="space-y-3 text-center">
				<p className="text-3xl" lang="th">
					{opening.questionText}
				</p>
				<button
					type="button"
					onClick={playQuestion}
					aria-label="Play question"
					className="inline-flex items-center justify-center w-20 h-20 rounded-full text-4xl"
					style={{
						background: "var(--color-surface-2)",
						color: "var(--color-primary)",
					}}
				>
					🔊
				</button>
			</section>

			<section className="space-y-3">
				{state === "idle" && <Button onClick={start}>Record your reply</Button>}
				{state === "recording" && (
					<Button onClick={stop}>Stop recording</Button>
				)}
				{state === "denied" && (
					<p role="alert">
						Microphone access needed — allow the microphone in your browser,
						then try recording again.
					</p>
				)}
				{state === "error" && (
					<p role="alert">
						Your microphone could not be started. Check that a recording device
						is connected and try again.
					</p>
				)}
				{state === "stopped" && judging && <p>Judging your reply…</p>}
				{state === "stopped" && judgement?.status === "unavailable" && (
					<p role="alert">{BACKEND_UNAVAILABLE_MESSAGE}</p>
				)}
				{state === "stopped" && judgement?.status === "ok" && (
					<div className="space-y-1">
						<p style={{ color: VERDICT_PRESENTATION[judgement.verdict].color }}>
							<strong>{VERDICT_PRESENTATION[judgement.verdict].label}</strong>
						</p>
						<p>{VERDICT_PRESENTATION[judgement.verdict].note}</p>
						<p>
							We heard: <span lang="th">{judgement.transcript}</span>
						</p>
						<p>{judgement.feedbackEn}</p>
					</div>
				)}
				{state === "stopped" && !judging && (
					<Button onClick={tryAgain}>Record another reply</Button>
				)}
			</section>
		</div>
	);
}

