/**
 * Whether conversation practice is unlocked for a learner, given their
 * current known-vocabulary and learned-grammar counts.
 *
 * Pure and dependency-free on purpose — both call sites (`Dashboard`,
 * `ConversationPracticePage`) already have these two counts on hand via
 * `AppContextValue.vocab`/`AppContextValue.lesson` (see CONTEXT.md: no new
 * `AppContextValue` member is needed), so this function never reaches into
 * storage or a service itself.
 *
 * Thresholds are gating-by-content-richness only (CONTEXT.md: a vocabulary
 * threshold tuned to fix live-generation compliance was measured not to
 * work and is not what this is for) — a learner needs enough known words
 * and grammar points for the pre-generated content bank to have anything
 * meaningful to draw from.
 */

/** Minimum distinct known vocabulary words required to unlock. */
export const MIN_VOCAB_COUNT = 200;

/** Minimum learned grammar points required to unlock. */
export const MIN_GRAMMAR_POINTS = 5;

export interface ConversationUnlockStatus {
	unlocked: boolean;
	/** How many more words are needed, 0 once the threshold is met. */
	vocabNeeded: number;
	/** How many more grammar points are needed, 0 once the threshold is met. */
	grammarNeeded: number;
}

/**
 * Both thresholds are inclusive — a learner at exactly `MIN_VOCAB_COUNT`
 * words and `MIN_GRAMMAR_POINTS` grammar points is unlocked, not one word
 * or one grammar point short of it.
 */
export function checkConversationUnlock(
	learnedVocabCount: number,
	learnedGrammarCount: number,
): ConversationUnlockStatus {
	const vocabNeeded = Math.max(0, MIN_VOCAB_COUNT - learnedVocabCount);
	const grammarNeeded = Math.max(0, MIN_GRAMMAR_POINTS - learnedGrammarCount);
	return {
		unlocked: vocabNeeded === 0 && grammarNeeded === 0,
		vocabNeeded,
		grammarNeeded,
	};
}

/**
 * Whether conversation practice is unlocked for a learner, given their
 * current known-vocabulary and learned-grammar counts.
 *
 * Pure and dependency-free on purpose — both call sites (`Dashboard`,
 * `ConversationPracticePage`) already have these two counts on hand via
 * `AppContextValue.vocab`/`AppContextValue.lesson` (see CONTEXT.md: no new
 * `AppContextValue` member is needed), so this function never reaches into
 * storage or a service itself.
 *
 * Thresholds are gating-by-content-richness only (CONTEXT.md: a vocabulary
 * threshold tuned to fix live-generation compliance was measured not to
 * work and is not what this is for) — a learner needs enough known words
 * and grammar points for the pre-generated content bank to have anything
 * meaningful to draw from.
 */

/** Minimum distinct known vocabulary words required to unlock. */
export const MIN_VOCAB_COUNT = 200;

/** Minimum learned grammar points required to unlock. */
export const MIN_GRAMMAR_POINTS = 5;

export interface ConversationUnlockStatus {
	unlocked: boolean;
	/** How many more words are needed, 0 once the threshold is met. */
	vocabNeeded: number;
	/** How many more grammar points are needed, 0 once the threshold is met. */
	grammarNeeded: number;
}

/**
 * Both thresholds are inclusive — a learner at exactly `MIN_VOCAB_COUNT`
 * words and `MIN_GRAMMAR_POINTS` grammar points is unlocked, not one word
 * or one grammar point short of it.
 */
export function checkConversationUnlock(
	learnedVocabCount: number,
	learnedGrammarCount: number,
): ConversationUnlockStatus {
	const vocabNeeded = Math.max(0, MIN_VOCAB_COUNT - learnedVocabCount);
	const grammarNeeded = Math.max(0, MIN_GRAMMAR_POINTS - learnedGrammarCount);
	return {
		unlocked: grammarNeeded === 0,
		vocabNeeded,
		grammarNeeded,
	};
}

import { useNavigate } from "react-router";
import { Badge } from "@/presentation/components/ui/badge";
import { Button } from "@/presentation/components/ui/button";
import { Card } from "@/presentation/components/ui/card";
import {
	checkConversationUnlock,
	MIN_GRAMMAR_POINTS,
	MIN_VOCAB_COUNT,
} from "../../domain/conversation/services/ConversationUnlockService";
import { SectionHeader } from "../components/atoms/SectionHeader";
import { ForecastCell } from "../components/molecules/ForecastCell";
import { LearnableCallout } from "../components/molecules/LearnableCallout";
import { QuickActionCard } from "../components/molecules/QuickActionCard";
import { StagePill } from "../components/molecules/StagePill";
import {
	ACHIEVEMENT_DEFS,
	AchievementBadge,
} from "../components/organisms/AchievementBadge";
import { HeatmapWidget } from "../components/organisms/HeatmapWidget";
import { NotificationBanner } from "../components/organisms/NotificationBanner";
import { useApp } from "../hooks/useApp";

const STAGES = [
	"Apprentice",
	"Guru",
	"Master",
	"Enlightened",
	"Burned",
] as const;

function newCountLabel(count: number, noun: string): string {
	return `${count} new ${noun}${count === 1 ? "" : "s"}`;
}

/**
 * Names the specific gap still blocking conversation practice — the vocab
 * gap if any remains, otherwise the grammar gap. Never a bare "locked"
 * label: every other locked/unlocked surface in this app names a number.
 */
function conversationGapMessage(
	learnedVocabCount: number,
	learnedGrammarCount: number,
): string {
	if (learnedVocabCount < MIN_VOCAB_COUNT) {
		return `${learnedVocabCount}/${MIN_VOCAB_COUNT} words learned`;
	}
	return `${learnedGrammarCount}/${MIN_GRAMMAR_POINTS} grammar points learned`;
}

export function Dashboard() {
	const { state, lesson, review, dashboard, vocab } = useApp();
	const navigate = useNavigate();

	const conversationUnlock = checkConversationUnlock(
		vocab.getLearnedCount(),
		lesson.getGrammarLearnedCount(),
	);

	const nextLesson = lesson.getNextScript();
	const nextVocabLesson =
		lesson.getVocabUnlockedCount() > 0 ? vocab.getNextLesson() : null;
	const nextGrammarLesson = lesson.getNextGrammar();
	const nextSentenceLesson = lesson.getNextSentence();
	const scriptDueCount = review.getDueCount("script");
	const vocabDueCount = review.getDueCount("vocab");
	const grammarDueCount = review.getDueCount("grammar");
	const sentenceDueCount = review.getDueCount("sentence");
	const dueCount =
		scriptDueCount + vocabDueCount + grammarDueCount + sentenceDueCount;
	const timeUntilNextReview = review.getTimeUntilNextReview();
	const forecast = review.getForecast();
	const leechCount = dashboard.getLeechCount();
	const stages = dashboard.getStageCounts();
	const achievements = state.achievements ?? [];
	const reviewButtonCount = [
		scriptDueCount,
		vocabDueCount,
		grammarDueCount,
		sentenceDueCount,
	].filter((n) => n > 0).length;
	const reviewGridClass = `grid gap-3 ${reviewButtonCount === 2 ? "grid-cols-2" : "grid-cols-1"}`;

	return (
		<div className="space-y-6 py-4">
			<NotificationBanner />

			{/* 1. Primary Action Card */}
			<div
				className="rounded-2xl p-6"
				style={{
					background:
						dueCount > 0 ? "var(--color-primary)" : "var(--color-surface-2)",
				}}
			>
				{dueCount > 0 ? (
					<>
						<div className="flex items-center gap-3 mb-4">
							<Badge variant="secondary">{dueCount} due</Badge>
							<span
								className="text-sm"
								style={{ color: "rgba(255,255,255,0.7)" }}
							>
								Cards ready for review
							</span>
						</div>
						<div className={reviewGridClass}>
							{scriptDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/review")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Script ({scriptDueCount})
								</Button>
							)}
							{vocabDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/vocabulary")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Vocab ({vocabDueCount})
								</Button>
							)}
							{grammarDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/grammar")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Grammar ({grammarDueCount})
								</Button>
							)}
							{sentenceDueCount > 0 && (
								<Button
									type="button"
									onClick={() => navigate("/sentences")}
									className="py-4 rounded-xl text-base font-semibold transition-colors"
									style={{
										background: "var(--color-accent)",
										color: "var(--color-text)",
									}}
								>
									Sentences ({sentenceDueCount})
								</Button>
							)}
						</div>
					</>
				) : (
					<>
						<p
							className="text-sm font-semibold mb-2"
							style={{ color: "var(--color-text-muted)" }}
						>
							All reviews complete
						</p>
						{timeUntilNextReview && (
							<p
								className="text-lg font-semibold"
								style={{ color: "var(--color-text)" }}
							>
								Next review in {timeUntilNextReview}
							</p>
						)}
					</>
				)}
			</div>

			{/* 2. Secondary Actions (2-col) — evergreen entry points, always in the
			    same two slots regardless of what else is unlocked. */}
			<div className="grid grid-cols-2 gap-3">
				{nextLesson ? (
					<QuickActionCard
						label="Next Lesson"
						value={`Lesson ${nextLesson}`}
						onClick={() => navigate(`/lesson/${nextLesson}`)}
					/>
				) : (
					<QuickActionCard label="Script" value="All done ✓" disabled />
				)}
				{/* Mobile-reachable entry point for the practice game — the
				    mobile tab row has no room for it. */}
				<QuickActionCard
					label="Game"
					value="Practice round"
					onClick={() => navigate("/game")}
				/>
			</div>

			{/* Conversation practice — reuses QuickActionCard in both states
			    (see task 3.2's Architectural Decision) rather than a second
			    visual treatment. The lock is enforced again at the page itself
			    (ConversationPracticePage), so this tile is a discoverability
			    affordance only, never the actual boundary. */}
			<div className="grid grid-cols-1 gap-3">
				{conversationUnlock.unlocked ? (
					<QuickActionCard
						label="Conversation Practice"
						value="Start a session"
						onClick={() => navigate("/conversation")}
					/>
				) : (
